func (w *Wallet) RevokeSession(id string) error {
	w.mu.Lock()
	defer w.mu.Unlock()

	sess, ok := w.sessions[id]
	if !ok {
		return fmt.Errorf("%w: %s", ErrSessionNotFound, id)
	}
	if sess.revoked {
		return nil
	}
	sess.revoked = true
	now := w.now()

	pending := make([]*request, 0)
	for _, req := range w.requests {
		if req.state == RequestPendingApproval && req.sessionID == sess.id {
			pending = append(pending, req)
		}
	}
	// 未到等待期限：随会话吊销进入拒绝终态（固定吊销理由、不填写审批账户）；
	// 恰到或超过期限的进入过期终态。
	w.settlePendingLocked(pending, now, func(req *request) {
		w.rejectPendingLocked(req, now, sessionRevokedRejectReason, "")
	})
	return nil
}

